    description: "古典時期之名，來自它所體現的古典價值：清晰、比例、形式的平衡，以及讓裝飾服從於結構。巴洛克音樂繁複、對位密集；古典音樂則追求透明與形式的優雅。這個轉變是有意識、刻意為之的，部分源自啟蒙哲學：音樂應該直接訴諸理性，也訴諸感受。\n\n落實在創作上，這意味著交響曲的發展——一種為管弦樂團而寫、通常三或四個樂章的大型作品——以及弦樂四重奏，一種由兩把小提琴、中提琴與大提琴組成的較小形式。Haydn 確立了這兩種形式，Mozart 把它們帶到完美，然後 Beethoven 到來，把它們改造成古典時期本身也容納不下的東西。\n\n自 1962 年起駐於 David Geffen Hall 的 New York Philharmonic，是美國最古老的交響樂團（創立於 1842 年），早在這座音樂廳落成之前，就已在演奏古典時期的交響曲。在這座廳裡聽一首 Haydn 或 Mozart 交響曲，等於在一個比 Carnegie Hall 還古老的機構裡聽音樂。"
