    description: "1973 年夏天，南布朗克斯是一個陷入危機的街區。房東縱火、經濟上的棄置、羅伯特·摩斯的跨布朗克斯快速道路硬生生剖開行政區心臟所造成的破壞——這個街區已被有系統地拆解。就在那樣的危機之中，三個人物創造出全然新的東西。\n\n1973 年 8 月 11 日，DJ Kool Herc 在 Sedgwick Avenue 1520 號發明了 loop：兩台唱盤、兩張同一首歌的唱片，把節奏間奏無限延長。Afrika Bambaataa 為它建立起文化的骨架——創立 Universal Zulu Nation、定義四大元素（DJ、MC、霹靂舞、塗鴉），把幫派的能量導向藝術。Grandmaster Flash 則把技術磨到極致，加上精準與表演性，讓街區派對的 DJ 台變成了真正的舞台。\n\n到了 1979 年，〈Rapper's Delight〉已把這個形式介紹給全世界。到了 1982 年，〈The Message〉證明它足以承載與美國最好的社會書寫同等的重量。九年之內，從 Morris Heights 的一間康樂室走上全國電台——嘻哈，就此登場。"
