    character: "自 1935 年以來,Village Vanguard 一直是全世界最重要的爵士俱樂部——不是最大,也不是最華麗,而是音樂始終最認真的那一間。Coltrane 在這裡錄下《Live at the Village Vanguard》。Miles Davis 在這裡演出過。Bill Evans 在這裡錄下《Sunday at the Village Vanguard》。Sonny Rollins 結束著名的 Williamsburg Bridge 閉關後,回到這裡錄音。這個房間只容得下 123 人。週一夜晚自 1966 年起從未間斷地屬於 Vanguard Jazz Orchestra。這裡,就是那個地方。",
