    character: "1891 年啟用的 Carnegie Hall,是美國最富傳奇的音樂殿堂。三個舞台——Stern Auditorium(2,804 席)、Zankel Hall(599 席)與 Weill Recital Hall(268 席)——涵蓋古典演出的每一種規模。古典音樂史上每一位重要藝術家都曾在此登台。Stern Auditorium 是主要的管弦樂場地;Zankel 主打當代與中型編制作品;Weill Recital Hall 則是紐約最出色的鋼琴獨奏與聲樂小廳。130 年過去,「登上 Carnegie Hall」依然是那個標準。",
