    character: "New York Botanical Garden 創立於 1891 年,起因是一位 Columbia 植物學家造訪 Kew Gardens 後,認定紐約也該有一座同等級的植物園。Enid A. Haupt Conservatory(1902)是全美最精美的維多利亞式玻璃溫室——棕櫚圓頂、雨林室、沙漠室——也是植物園著名季節大展的舞台(春天的 Orchid Show、冬天的 Holiday Train Show)。Thain Family Forest 則是曾經覆蓋整個紐約市的原始森林最大殘存:五十英畝伐木工人從未染指的林地,Bronx River 從下方的峽谷穿流而過。先搭一趟遊園車認路,然後用走的。",
