    character: "Louis Armstrong 大可住在世界任何地方。他卻在 1943 年買下 Corona 一條工人階級街區上的紅磚小屋,一直住到 1971 年過世——為鄰居小孩開門、在轉角的中餐館吃飯、在自己的小房間裡錄下自己說話和吹奏的聲音。這棟房子是國家歷史地標,依 Lucille 生前打理的樣子完整保存:土耳其藍的廚房、鑲滿鏡子的浴室、放著他的盤帶和小號的房間。街對面新落成的 Louis Armstrong Center 收藏著他的檔案——六萬件,是所有爵士音樂家中規模最大的。40 分鐘的導覽,是全美國最親密的音樂家故居體驗,而這個街區本身就是重點:世界最偉大的表演者,家在 Queens。",
    insiderTip: "導覽從街對面的 Louis Armstrong Center 出發——早點到,先看檔案展,再參加 40 分鐘的故居導覽。Satchmo 的小房間裡播著他親手剪接的錄音拼貼,那是最多人掉淚的房間。",
    bookingNote: "導覽整點出發,僅週四至週六——請提前預約;每團人數不多",
    admissionCost: "成人 $20 · 長者 $14 · 5 歲以下免費",
    visitDuration: "1–1.5 小時"
