    character: "Madison Square Garden 是第四座使用這個名字的場館,自 1968 年持續營運至今。它是 New York Knicks(NBA)與 New York Rangers(NHL)的主場,舉辦過的世界拳王戰比史上任何場館都多。懸掛在天花板的冠軍旗幟——Knicks 的冠軍、Rangers 的 Stanley Cup、橫跨五十多年的兩隊退役背號——是全美最濃縮的體育歷史展示之一。紐約體壇發生大事的時候,通常就發生在這裡。",
    insiderTip: "開賽前抬頭看——從 1970 年到今天的冠軍旗幟,把整部紐約體育史寫在同一片天花板上。",
