    character: "全世界最大的網球場有 23,771 個座位,以 1968 年首屆 US Open 冠軍為名。Arthur Ashe 是第一位登上世界第一的非裔美籍選手,也是 1993 年因 AIDS 病逝前,唯一拿下三座大滿貫單打冠軍的非裔美籍男子選手。以他為名的球場,每年 8、9 月上演為期兩週、全世界強度最高的國際網球對決。園區裡還有 Louis Armstrong Stadium 和 Grandstand——觀看會外賽與前幾輪的絕佳球場,常常免費或票價低廉。",
