    character: "1930 年的十一個月裡,這是地球上最高的建築,而建築師 William Van Alen 為了給對手一個驚喜,事先把尖塔藏在冠頂裡。Nirosta 不鏽鋼外皮在當時是革命性的——這是第一棟把不鏽鋼當作裝飾外衣的重要建築。光為了大廳就值得走進去:紅色摩洛哥大理石、描繪工廠景象的琥珀色壁畫、鑲嵌異國木材的 Art Deco 電梯門。1920 年代「工業即是美」的信念,就是在這裡凝結成石灰岩與鋼鐵。",
    insiderTip: "走進大廳——鑲嵌異國木材的 Art Deco 電梯門,和描繪工廠景象的琥珀色壁畫,是紐約所有摩天樓中最精緻的室內細節之一。",
    bookingNote: "平日上班時間可直接進入;無觀景台",
