    character: "Warren & Wetmore 與 Reed & Stem 圍繞著一個想法設計這座車站:抵達紐約,應該是一件有紀念碑感的事。Main Concourse 長 275 英尺、寬 120 英尺、高 125 英尺——刻意做成大教堂的尺度。著名的土耳其藍天花板繪著冬季星空,而且是反著畫的;設計者的解釋是,這是從上帝的視角俯瞰天空。地面下的坡道系統——兩層共 44 條軌道——是與地上建築同樣優雅的工程解答。1960 年代它險遭拆除;它的倖存,催生了紐約市的歷史保存法。",
