    character: "Daniel Burnham 拿到 Broadway 與 Fifth Avenue 交會處的一塊三角形基地,蓋出了 Fuller Building——一棟披著石灰岩與陶磚的鋼骨摩天樓,向南收窄成六英尺寬的船艏。這棟建築證明了鋼骨結構這套新系統,能創造出真正優雅的東西,而不只是高而已。Burnham 用文藝復興與巴洛克式的裝飾細節——壁柱、簷口、粗石砌基座——為工業技術鍍上歷史的血統。它在街面掀起的風曾惡名昭彰,會吹起女士的裙襬;警察用俚語「23 skidoo」驅散圍觀人群。",
