    character: "James Renwick Jr. 研究過法國與英國的哥德大教堂,立志在 Fifth Avenue——當時還是遠在市中心之外的一條塵土路——蓋出足以與之比肩的美國版本。白色大理石外牆、330 英尺高的雙尖塔、中殿拱頂 112 英尺的室內高度:這些在美國宗教建築中都是前所未有。Renwick 使用哥德的結構邏輯——尖拱、飛扶壁、肋拱——不是當裝飾,而是當一套真正的工程系統。彩繪玻璃窗,包括直徑 26 英尺的玫瑰窗,讓室內浸在隨日光流轉而變幻的彩色光線裡。",
