    character: "Le Corbusier 是國際設計委員會十二位建築師之一，但最終勝出的是他的方案——垂直的玻璃板樓。Secretariat 大樓開創了建築作為純粹玻璃矩形的概念：兩個寬面全部覆以玻璃，兩個窄端則是實心大理石。建築群還包括頂部曲線獨特的 General Assembly 大樓。園區位於國際領土上——嚴格來說不屬於紐約市——這是對機構宗旨刻意為之的象徵。公眾導覽會帶你看到滿是會員國贈禮藝術品的內部空間。",
