    character: "1783 年 12 月 4 日，George Washington 把軍官們召集到樓上的 Long Room 道別。獨立戰爭已然結束，而正處權力巔峰、大可自立為王的 Washington，選擇辭去統帥職務回家去。Long Room 至今仍在，已復原為 1783 年的樣貌。酒館本身是一棟 1719 年的喬治亞式紅磚建築，是紐約市現存最古老的建築之一。地下室與一樓是餐廳；樓上則是獨立戰爭時期的博物館，收藏當年的文物與文件。",
