    character: "Arturo Schomburg 是一位有非裔加勒比血統的波多黎各人，畢生蒐集非洲人與非裔美國人撰寫、以及與之相關的書籍、手稿與文物——而那個年代的學院史學，幾乎把黑人從敘事中抹除。1925 年，他把 5,000 件收藏賣給 New York Public Library，Harlem 分館成了它的家。館藏如今超過 1,100 萬件：James Van Der Zee 的攝影檔案、W.E.B. Du Bois 的文稿、Langston Hughes 的文稿，以及別處無存的 Harlem Renaissance 文獻。閱覽室對研究者開放；藝廊展覽免費。",
