    character: "這棟位於 Morris Heights 的六層住宅大樓，是音樂史上最重要、卻最少人聽過的地址。Clive Campbell——DJ Kool Herc——12 歲時從 Kingston, Jamaica 搬來這裡。他的妹妹 Cindy 為了籌返校費用，在 1973 年 8 月 11 日辦了那場派對。那一夜他用兩台唱盤做的事，創造出一門全新的藝術。大樓至今仍是住宅，一塊牌匾標記著它的意義。而它周圍的一切——公園、街道、社區——正是孕育嘻哈的地理。",
