    character: "Universal Hip Hop Museum 就座落在五十年前嘻哈誕生的 Bronx——這是刻意的選擇。展廳梳理四大元素（DJ、MC、Breaking、塗鴉）、這個樂種數十年來的演變，以及它如何從一種街坊藝術，蛻變為過去半世紀全球影響力最大的流行音樂。檔案庫收藏原始器材、稀有錄音、演出服裝與文件。輪展則邀來當代藝術家與學者。這是第一座完全獻給這段歷史的常設機構。",
