    character: "Rucker Park 是籃球與嘻哈在 Harlem 的露天空氣中相遇的地方。Entertainers Basketball Classic（EBC）夏季錦標賽曾吸引 Kobe Bryant、Kevin Durant 與 LeBron James 前來與在地傳奇同場較勁。1990 與 2000 年代，嘻哈歌手——Jay-Z、Nas、Busta Rhymes、DMX——會在場邊開唱，音樂從喇叭轟出，人群三排深地擠在圍欄邊。這是紐約最民主的娛樂：免費、露天、徹底鮮活。",
