    character: "Queensbridge Houses 位於 Long Island City，在 Queensboro Bridge 的陰影下，隔著 East River 與 Midtown Manhattan 正面相望。從住宅的窗戶就能看見 Manhattan 天際線——Nas 在 Illmatic 裡把這份反諷煉成了詩。整個社區有數十棟建築、超過 6,000 名居民，內部街道自成棋盤。Nas 1994 年的首張專輯以驚人的具體與詩意描繪這片地理，把在地自傳昇華為普世文學。Mobb Deep——Prodigy 與 Havoc——同樣出身 Queensbridge，寫出了同一枚硬幣更暗、更冷的那一面。",
