    character: "Carbone 於 2013 年在 Thompson Street 上舊 Rocco's 的原址開幕，立刻成為紐約義裔美式餐廳的柏拉圖式理想型。穿著酒紅色 Zac Posen 晚禮服的領檯在桌邊現拌凱薩沙拉，spicy rigatoni vodka 是全 NYC 被拍最多的一道 pasta，光是麵包籃（whipped ricotta + garlic knots + soppressata）就值得走一趟。訂位在 Resy 上提前整整 30 天、早上 10 點準時開放，不到 60 秒就被搶光。",
