    character: "夫妻檔 Scott Tacinelli 和 Angie Rito 在 2017 年開了 Don Angie，重新定義了紐約約會之夜的義大利餐廳可以是什麼樣子。招牌 pinwheel lasagna（$46，兩人份）堪稱經典——麵皮捲成花朵狀，外層再煎到酥脆。菊花沙拉是最搶戲的開胃菜。鏡面天花板配粉紅色卡座的 Art Deco 內裝，簡直像是專為求婚設計的。",
