    character: "Veselka 由烏克蘭移民 Wolodymyr 和 Olha Darmochwal 於 1954 年創立，從此一直守在 9th Street 和 2nd Avenue 的街角。pierogi 每天現做（水煮或油煎皆可），這裡的羅宋湯是 NYC 所有版本都要對標的基準。24 小時營業——凌晨 3 點想吃頓真正的食物時，這裡就是目的地。",
