    character: "Eleven Madison Park 於 1998 年在 Art Deco 風格的 Metropolitan Life North Building 裡開幕。Daniel Humm 在 2006 年接手，把它推上米其林三星，並於 2017 年登上 World's 50 Best 榜首。2021 年餐廳重新出發，全面改為植物性料理——NYC 高級餐飲史上最具爭議的決定。用餐空間是全美最美之一；整場體驗如同一齣戲。",
