    character: "Statue of Liberty 由 Frédéric Auguste Bartholdi 設計，內部鐵骨架出自 Gustave Eiffel（對，就是那位 Eiffel）之手，1886 年由法國贈予美國。這座 305 英尺的銅像原本是新銅的棕色；如今的綠色，是頭 30 年間逐漸氧化生成的銅綠。光是基座就有 154 英尺。從 Battery Park（Manhattan）或 Liberty State Park（NJ）出發的渡輪涵蓋 Liberty + Ellis Island；「crown access」登冠票常常提前數月售罄。",
    insiderTip: "從 Whitehall Terminal 搭免費的 Staten Island Ferry，就能從水上把 Statue 看得清清楚楚——如果不執著於親自踏上 Liberty Island，搭 SI ferry 就好，省下 $24。若真要登島，請把一整天留給 Liberty + Ellis Island（兩者是聯票）。",
